// Normalize both entry paths (webhook body-wrapped, or direct from Tool Workflow trigger) into one consistent shape, and validate before anything downstream runs.
const raw = $json.body || $json;
const triggerSource = $json.body ? 'webhook' : 'workflow';
try {
const operation = String(raw.operation || '').toLowerCase();
const validOps = ['create', 'write', 'update', 'get', 'remove'];
// Review state is writable only through the authenticated native Review gate.
if (String(raw.id) === '5xZbQOeVq0mh9cJu' && operation !== 'get') { const e=new Error('Review state requires authenticated Review transport'); e.statusCode=403; throw e; }

if (!validOps.includes(operation)) {
  throw new Error(`Invalid operation "${raw.operation}". Must be one of: ${validOps.join(', ')}`);
}
if (operation !== 'create' && !raw.id) {
  throw new Error(`Missing required "id" (data table ID) for operation "${operation}"`);
}
if (['write', 'update', 'create'].includes(operation) && !raw.row) {
  throw new Error(`Missing required "row" for operation "${operation}"`);
}
if (operation === 'update' && (!raw.row || typeof raw.row !== 'object' || Array.isArray(raw.row) || Object.keys(raw.row).length === 0 || Object.values(raw.row).every(v => v === undefined))) {
  throw new Error('For "update", row must be a non-empty object of data columns');
}
if (operation === 'update' && (!raw.match || raw.match.id === undefined || raw.match.id === null)) {
  throw new Error('Missing required "match.id" for update operation');
}
if (operation === 'write' && !Array.isArray(raw.row?.data)) {
  throw new Error('For "write", row.data must be an array of row objects, e.g. { "data": [{...}] }');
}
if (operation === 'create' && (!raw.row?.name || !Array.isArray(raw.row?.columns))) {
  throw new Error('For "create", row must include "name" and a "columns" array');
}

if (raw.limit !== undefined && (!Number.isInteger(raw.limit) || raw.limit < 1 || raw.limit > 250)) throw new Error('limit must be an integer from 1 to 250');
if (raw.cursor !== undefined && typeof raw.cursor !== 'string') throw new Error('cursor must be a string');
return [{
  json: {
    limit: raw.limit || 100,
    cursor: raw.cursor || "",
    operation,
    id: raw.id || null,
    row: raw.row || null,
    match: raw.match || null,
    _triggerSource: triggerSource
  }
}];
} catch (e) {
 if (triggerSource !== "webhook") throw e;
 return [{json:{_validationError:true,error:"invalid_request",message:e.message,statusCode:e.statusCode===403?403:400}}];
}
